#!/usr/bin/env python3
"""Reproduce the Phase-1 benchmark record.

Prints the three tables in `docs/OLYMPUS_NATIVE_REPRESENTATIONS.md` §3 and §6:
every baseline and the native network on a structured synthetic process, the
same on a random walk, and the seven representation candidates on
reconstruction.

**Every series here is synthetic and generated by this file.** The numbers are
evidence about the pipeline and about the candidates' relative behaviour. They
are not evidence about markets; no market-data provider is reachable from this
environment (blocker B1, `docs/OLYMPUS_NATIVE_MODEL_STATUS.md` §4).

The random-walk run is the one that makes the first table worth reading. If a
model shows an edge there, the harness is measuring something other than skill
and every verdict in the first table is meaningless.

    python scripts/native_benchmark.py            # needs the `native` extra

Without torch, seven of the nine baselines still run and the representation
comparison is skipped; the report says which opponents did not run rather than
quietly comparing against fewer.
"""

from __future__ import annotations

import argparse
import json
import math
import random
import sys
from datetime import datetime, timedelta, timezone

from olympus.trading.contracts import Candle
from olympus.trading.native import benchmark as BM
from olympus.trading.native import dataset as D
from olympus.trading.native import torchutil as TU
from olympus.trading.native.data import make_windows

START = datetime(2027, 6, 1, tzinfo=timezone.utc)
KEY = "SIM:B"
LOOKBACK = 33
HORIZON = 3


def ar1(n: int = 1200, seed: int = 5, phi: float = 0.97,
        noise: float = 0.001) -> list[float]:
    """A linear process. The linear baselines should win on it."""
    rng = random.Random(seed)
    prices, step = [100.0], 0.0
    for _ in range(n - 1):
        step = phi * step + rng.gauss(0.0, noise)
        prices.append(prices[-1] * math.exp(step))
    return prices


def random_walk(n: int = 1200, seed: int = 9, sigma: float = 0.003) -> list[float]:
    """No structure at all. The negative control."""
    rng = random.Random(seed)
    prices = [100.0]
    for _ in range(n - 1):
        prices.append(prices[-1] * math.exp(rng.gauss(0.0, sigma)))
    return prices


def bars(prices) -> list[Candle]:
    return [Candle(instrument_key=KEY, timeframe="1h",
                   ts_open=START + timedelta(hours=i),
                   ts_close=START + timedelta(hours=i + 1),
                   open=p, high=p * 1.004, low=p * 0.996, close=p,
                   volume=1000.0 + i)
            for i, p in enumerate(prices)]


def run_models(prices, label: str, *, epochs: int, as_json: bool):
    windows = make_windows(bars(prices), lookback=LOOKBACK, horizon=HORIZON)
    split = D.three_way_split(windows, train_fraction=0.6,
                              validation_fraction=0.2)

    models = {}
    if TU.torch_available():
        from olympus.trading.native import neural as N
        config = N.NeuralConfig(lookback=LOOKBACK, horizon=HORIZON, patch_len=4,
                                d_model=16, n_layers=2, epochs=epochs,
                                batch_size=64, learning_rate=1e-2)
        models["olympus_native"] = BM.NativeEntrant(N.NeuralQuantileModel(config),
                                                    seed=0)

    report = BM.run_benchmark(train=split.train, test=split.test,
                              horizon=HORIZON, models=models)
    if as_json:
        print(json.dumps({"label": label, "split": list(split.sizes),
                          **report.to_dict()}, indent=2))
        return report

    print(f"\n### {label}")
    print(f"train/validation/test = {split.sizes}   "
          f"costs = {report.costs.round_trip_bps:.1f} bp round trip")
    print(report.table())
    print("winners:", ", ".join(report.winners) or "(none)")
    return report


def run_representations(*, epochs: int, as_json: bool):
    if not TU.torch_available():
        print("\n### Representation candidates — skipped (torch absent)")
        return
    from olympus.trading.native import representations as R

    windows = make_windows(bars(ar1()), lookback=17, horizon=HORIZON)
    config = R.RepresentationConfig(lookback=16, patch_len=4, d_model=16,
                                    codebook_size=16)
    tensor = R.windows_to_tensor(windows, config)
    cut = int(len(windows) * 0.7)
    results = R.compare_representations(tensor[:cut], tensor[cut:],
                                        config=config, epochs=epochs, seed=0)
    if as_json:
        print(json.dumps([r.to_dict() for r in results], indent=2))
        return
    print("\n### Representation candidates — reconstruction on the AR(1) windows")
    print(R.comparison_table(results))
    print("\nThe ordering is not the conclusion: multi_resolution_patch carries "
          "3.5x\nthe latent positions and breaks the single time order a causal "
          "trunk needs.")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--epochs", type=int, default=60,
                        help="training epochs for the native model (default 60)")
    parser.add_argument("--repr-epochs", type=int, default=30,
                        help="training epochs per representation (default 30)")
    parser.add_argument("--json", action="store_true",
                        help="machine-readable output")
    args = parser.parse_args()

    if not args.json:
        print("=" * 100)
        print("PHASE 1 BENCHMARK RECORD — SYNTHETIC DATA ONLY")
        print("Nothing here is evidence about markets. See blocker B1 in")
        print("docs/OLYMPUS_NATIVE_MODEL_STATUS.md §4.")
        print("=" * 100)
        if not TU.torch_available():
            print("\ntorch is absent: the two torch baselines and the native "
                  "model will not run.\nInstall the `native` extra to reproduce "
                  "the published tables.")

    run_models(ar1(), "AR(1) phi=0.97 sigma=0.001 — a LINEAR process",
               epochs=args.epochs, as_json=args.json)
    control = run_models(random_walk(),
                         "Random walk sigma=0.003 — NO structure (negative control)",
                         epochs=args.epochs, as_json=args.json)
    run_representations(epochs=args.repr_epochs, as_json=args.json)

    if control.winners and not args.json:
        print("\nWARNING: a model beat persistence on white noise. The harness "
              "is measuring\nsomething other than skill and the first table "
              "should not be trusted.")
        return 1
    return 0


if __name__ == "__main__":                               # pragma: no cover
    sys.exit(main())
